<script>
const nav=document.getElementById('floatingNav');
const toggle=document.getElementById('navToggle');
toggle.addEventListener('click',()=>{nav.classList.toggle('collapsed');toggle.textContent=nav.classList.contains('collapsed')?'\u25b6':'\u2630';});

const cards = document.querySelectorAll('.case-card');
const obs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('revealed'); obs.unobserve(e.target); } });
}, { threshold: 0.1 });
cards.forEach(c => obs.observe(c));
function animateCount(e){var t=parseInt(e.dataset.target),n=0,s=Math.max(Math.ceil(t/60),1),i=setInterval(function(){n=Math.min(n+s,t),e.textContent=n.toLocaleString(),n>=t&&clearInterval(i)},16)}var so=new IntersectionObserver(function(e){e.forEach(function(e){e.isIntersecting&&(animateCount(e.target),so.unobserve(e.target))})},{threshold:.5});document.querySelectorAll(".counting").forEach(function(e){so.observe(e)});
</script>

</body>
</html>

